def calculator():
    print('=== 简单计算器 ===')
    try:
        num1 = float(input('输入第一个数字: '))
        op = input('输入运算符 (+, -, *, /): ')
        num2 = float(input('输入第二个数字: '))

        if op == '+':
            result = num1 + num2
        elif op == '-':
            result = num1 - num2
        elif op == '*':
            result = num1 * num2
        elif op == '/':
            if num2 == 0:
                print('错误：除数不能为零')
                return
            result = num1 / num2
        else:
            print('不支持的运算符')
            return

        print(f'结果: {num1} {op} {num2} = {result}')
    except ValueError:
        print('错误：请输入有效的数字')

def calculator_v2():
    print('=== 计算器v2 ===')
    num1 = float(input('数字1: '))
    num2 = float(input('数字2: '))

    results = {
        '+': num1 + num2,
        '-': num1 - num2,
        '*': num1 * num2,
        '/': num1 / num2 if num2 != 0 else '错误'
    }

    for op, result in results.items():
        print(f'{num1} {op} {num2} = {result}')

import math

def scientific_calc(num, op):
    if op == 'sqrt':
        return math.sqrt(num)
    elif op == 'sin':
        return math.sin(math.radians(num))
    elif op == 'cos':
        return math.cos(math.radians(num))
    else:
        return '不支持的运算'

print(f'sqrt(16) = {scientific_calc(16, "sqrt")}')
print(f'sin(30) = {scientific_calc(30, "sin")}')

def word_frequency(filename):
    with open(filename, 'r') as f:
        words = f.read().lower().split()

    freq = {}
    for word in words:
        if word in freq:
            freq[word] += 1
        else:
            freq[word] = 1

    sorted_freq = sorted(freq.items(), key=lambda x: x[1], reverse=True)
    return sorted_freq[:10]

top10 = word_frequency('article.txt')
print('TOP 10 高频词:')
for word, count in top10:
    print(f'{word}: {count}')
